function catBySlug(s){ for(var i=0;i<CATS.length;i++){ if(CATS[i].slug===s) return CATS[i]; } return null; }
function esc(s){ return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function initials(name){ var w=name.replace(/[^A-Za-z0-9 ]/g,"").split(" ").filter(Boolean); return (w[0]?w[0][0]:"")+(w[1]?w[1][0]:""); }
function disclosureHTML(){
 return '<div class="disclosure"><strong>Affiliate disclosure:</strong> As an Amazon Associate I earn from qualifying purchases. Check price on Amazon before buying, as prices and availability change. <a href="#/disclosure">Read the full disclosure</a>.</div>';
}
function faqHTML(list,big){
 return list.map(function(qa){ return '<details><summary>'+esc(qa[0])+'</summary><p>'+esc(qa[1])+'</p></details>'; }).join("");
}
function cardHTML(p){
 var c=catBySlug(p.cat);
 var feats=p.feats.map(function(f){return "<li>"+esc(f)+"</li>";}).join("");
 var img=IMG[p.asin]||"";
 var faqs=FAQ[p.asin]||[];
 var who = p.who ? '<div class="who-box"><p><strong>Who it is for:</strong> '+esc(p.who)+'</p>'+(p.skip?'<p><strong>Who should skip it:</strong> '+esc(p.skip)+'</p>':"")+'</div>' : "";
 var pc = (p.pros||p.cons) ? '<div class="pc">'+(p.pros?'<div class="pros"><b>Pros</b>'+esc(p.pros)+'</div>':"")+(p.cons?'<div class="cons"><b>Cons to know</b>'+esc(p.cons)+'</div>':"")+'</div>' : "";
 return '<article class="prod">'
  +'<div class="ph"><img src="'+img+'" alt="'+esc(p.name)+'" loading="lazy"></div>'
  +'<span class="cat-tag">'+esc(c.name)+'</span>'
  +'<h3>'+esc(p.name)+'</h3>'
  +'<p class="price">'+esc(p.price)+'<small>Prices change, check the live price on Amazon before buying.</small></p>'
  +'<p class="desc">'+esc(p.desc)+'</p>'
  + who + pc
  +'<p class="feat-label">Key features</p><ul class="feats">'+feats+'</ul>'
  +(faqs.length?'<div class="faq"><p class="faq-label">FAQs</p>'+faqHTML(faqs)+'</div>':"")
  +'<a class="buy" href="'+p.link+'" target="_blank" rel="sponsored nofollow noopener">Buy on Amazon <span class="arr">\u2197</span></a>'
  +'</article>';
}
function genFaqSection(extra){
 var list=GENFAQ.slice(); if(extra){ list=extra.concat(list); }
 return '<section><div class="sec-head"><div><h2>Frequently asked questions</h2><p>Quick answers about the products, how to use them and who they suit.</p></div></div><div class="faq-big">'+faqHTML(list,true)+'</div></section>';
}
function guideBoxHTML(){
 return '<section><div class="guide-box"><h2>How sharing and links work here</h2><p><strong>Link checks:</strong> We check the Amazon links on this site once a month and remove or replace links for products that are out of stock or no longer available. Availability can still change between checks, so confirm on Amazon before buying.</p><p><strong>Pinterest:</strong> Pins link to a page on this site, not directly to Amazon, so you can read the full description, who a product is for and the FAQs first. Pin descriptions include an affiliate disclosure such as #ad or affiliate link.</p><p><strong>Prices:</strong> This site does not list fixed prices. Check price on Amazon for the current price.</p></div></section>';
}
function staticShell(title, intro, body){
 renderNav("__info__");
 document.getElementById("app").innerHTML = '<div class="wrap"><p class="crumb"><a href="#/">Home</a> / '+esc(title)+'</p><div class="page-head"><h1>'+esc(title)+'</h1><p>'+esc(intro)+'</p></div>'+disclosureHTML()+'<div class="static-page">'+body+'</div></div>';
 window.scrollTo(0,0);
}
function renderAbout(){
 staticShell("About Fury Sales","Handpicked gift ideas, cozy home finds, Korean skincare and kids' toys, explained honestly before you buy.", '<p>Fury Sales is a small shopping guide site for readers in the United States. It collects handpicked finds in one place: gift ideas, cozy home finds, Korean skincare, kids\u2019 toys and games, plus everyday tech, audio, fashion and car accessories. Every product is written up in plain English so you can decide quickly and confidently.</p><h2>What you will find here</h2><ul><li><strong>Gift ideas</strong> for birthdays, holidays and the people who are hard to buy for.</li><li><strong>Cozy home finds</strong>, from soft blankets to festive curtain lights.</li><li><strong>Korean skincare</strong> picks, explained step by step, including who each one suits.</li><li><strong>Kids\u2019 toys and games</strong>, with the age guide and player count stated up front.</li></ul><h2>Honest notes, not just links</h2><p>Each product card gives a plain description, the key features, who it is for and who should skip it, plus pros and cons to know before you spend anything. If a product needs an extra part, a membership or a certain age, that is written on the card, not hidden. Prices are never printed here because they change; every card simply says check price on Amazon.</p><h2>How this site earns</h2><p>Fury Sales is an affiliate site. As an Amazon Associate I earn from qualifying purchases, which means a small commission when you buy through a link here, at no extra cost to you. See the <a href="#/disclosure">Affiliate Disclosure</a> page for the full detail, and the <a href="#/contact">Contact</a> page if you spot a wrong detail or a broken link.</p>');
}
function renderContact(){
 staticShell("Contact","Send a message about a product, a link or a correction, and it lands straight in the Fury Sales inbox.", '<p>Use the form below to ask about a product listed here, report a broken link, or point out a wrong detail in a description. Your message is delivered by email, and replies come back to the email address you enter.</p><form class="contact-form" action="https://formsubmit.co/ig54itachi@gmail.com" method="POST"><input type="hidden" name="_next" value="https://mhassan-dev13.github.io/fury-sales/#/thanks"><input type="hidden" name="_subject" value="New message from the Fury Sales website"><input type="hidden" name="_template" value="table"><input type="text" name="_honey" style="display:none" tabindex="-1" autocomplete="off"><label>Your name<input type="text" name="name" required autocomplete="name" placeholder="e.g. Alex Morgan"></label><label>Your email<input type="email" name="email" required autocomplete="email" placeholder="you@example.com"></label><label>Your message<textarea name="message" required placeholder="Write your question or the product name and what looks wrong\u2026"></textarea></label><button type="submit">Send message</button><p class="form-note">Messages are used only to reply to you and to fix the issue you raised. Please do not send payment details or Amazon passwords; no message about this site will ever ask for them.</p></form><h2>Before you write</h2><ul><li>For delivery, returns and refunds, contact Amazon through your Amazon order, as Amazon handles the sale.</li><li>For a link that does not open the right product, include the product name and the category page you found it on, so it can be checked in the monthly link check or sooner.</li></ul><p>Product details and availability can change on Amazon without notice, so check the live Amazon page for the final detail before buying.</p>');
}
function renderThanks(){
 staticShell("Thanks","Your message has been sent.", '<p>Thanks for getting in touch. Your message has been sent and is on its way to the Fury Sales inbox. We read every message and will reply soon, usually within a couple of days, to the email address you entered in the form.</p><p>If your message was about a broken link or a wrong product detail, thanks for flagging it, it will be checked and fixed.</p><p style="margin-top:22px"><a class="buy" href="#/" style="max-width:280px">Back to Home <span class="arr">\u2197</span></a></p>');
}
function renderPrivacy(){
 staticShell("Privacy Policy","What this site collects, what it does not, and how affiliate links and cookies work.", '<p>Last updated: 20 November 2026.</p><p>Fury Sales is a product guide and affiliate site. It has no user accounts, no sign-up, no checkout and no comments section, and it does not sell products directly. Purchases are completed on Amazon. This page explains, in plain language, what information is collected when you use this site.</p><h2>Information we collect</h2><p>The only personal information this site receives is what you choose to send through the <a href="#/contact">Contact</a> form: your name, your email address and your message. Contact form messages are delivered by email through FormSubmit, a form delivery service, and are kept only so we can reply to you and fix the issue you raised, such as a broken link or a wrong description. We do not collect payment details, and you should never send them.</p><h2>We do not sell your data</h2><p>Your personal information is never sold, rented or traded to anyone. It is not shared with third parties for their own marketing.</p><h2>Cookies and Amazon affiliate links</h2><p>This site itself does not set advertising or tracking cookies. When you click a link to Amazon, Amazon may place cookies on your device under its own privacy policy. Those cookies let Amazon recognise that you arrived from this site, so a qualifying purchase can be credited to this site, and they also help Amazon run its store. As an Amazon Associate I earn from qualifying purchases. You can block or delete cookies in your browser settings at any time; the guides on this site will still work, but a purchase may not be credited to this site.</p><h2>Third-party services</h2><ul><li><strong>Amazon:</strong> product pages, prices, checkout, delivery and returns are handled by Amazon under Amazon\u2019s own privacy policy.</li><li><strong>FormSubmit:</strong> delivers contact form messages to our email inbox. It processes the name, email and message you submit for that delivery.</li></ul><h2>Your choices</h2><p>If you sent a message through the contact form and want it deleted, write again through the same form and ask, and it will be removed from the inbox. You can also browse this site without sending any personal information at all.</p><h2>Children</h2><p>This site is written for adult shoppers. Toy and game pages describe products for children, but purchases are made by adults on Amazon.</p><h2>Changes to this policy</h2><p>If this policy changes, the updated text will be posted on this page with a new date at the top.</p><h2>Contact</h2><p>Questions about this policy can be sent through the <a href="#/contact">Contact</a> page.</p>');
}
function renderDisclosurePage(){
 staticShell("Affiliate Disclosure","The full disclosure for affiliate links on Fury Sales.", '<p><strong>As an Amazon Associate I earn from qualifying purchases.</strong></p><p>Fury Sales takes part in the Amazon Associates Program. When you buy through a link on this site, I may earn a small commission at no extra cost to you. That commission helps keep the guides free to read.</p><h2>Where disclosure appears</h2><p>The short disclosure appears at the top of this site, near the top of the home page and every category page, and in the footer, not only on this page. Buy buttons link to Amazon and use rel="sponsored nofollow".</p><h2>Prices and availability</h2><p>This site does not list fixed product prices, because prices and stock change. Every card says Check price on Amazon. Check the live price and availability on Amazon before buying.</p><h2>Links, images and checks</h2><p>Links on this site are not shortened or cloaked with third-party shorteners. We check links once a month and remove or replace links for out-of-stock or removed products. Product images on this preview are separate image files; on a live Associates site, product images should come through SiteStripe or the Product Advertising API, so image sourcing should be confirmed before a public launch.</p><h2>Pinterest</h2><p>Pins for this site link to a page on this site, not directly to Amazon. Pin descriptions should include a disclosure such as #ad or affiliate link.</p><h2>No self-purchases</h2><p>Do not buy through your own affiliate links. Purchases through your own links do not earn commission and can put an Associates account at risk.</p>');
}
