 document.getElementById("app").innerHTML=
  '<div class="hero"><div class="wrap"><h1>Useful finds, explained before you buy.</h1><p>Every product here comes with a plain description, the key features that actually matter, and an honest price note, so you can decide in seconds and check the live price on Amazon.</p><a class="cta" href="#/tech">Browse Tech &amp; Electronics</a><div class="stats"><div><b>'+PRODUCTS.length+'</b><span>Products listed</span></div><div><b>8</b><span>Categories</span></div><div><b>Check price</b><span>On Amazon, before buying</span></div></div></div></div>'
  +'<div class="wrap">'+disclosureHTML()
