function route(){
 var h=location.hash.replace(/^#\/?/,"").split("?")[0];
 if(!h){ renderHome(); return; }
 if(h==="about"){ renderAbout(); return; }
 if(h==="contact"){ renderContact(); return; }
 if(h==="thanks"){ renderThanks(); return; }
 if(h==="privacy"){ renderPrivacy(); return; }
 if(h==="disclosure"){ renderDisclosurePage(); return; }
 if(catBySlug(h)){ renderCat(h); return; }
 renderHome();
}
var menuBtn=document.getElementById("menuBtn");
var navEl=document.getElementById("nav");
function setMenu(open){
 navEl.classList.toggle("open",open);
 menuBtn.setAttribute("aria-expanded",open?"true":"false");
 menuBtn.setAttribute("aria-label",open?"Close menu":"Open menu");
}
menuBtn.addEventListener("click",function(){ setMenu(!navEl.classList.contains("open")); });
navEl.addEventListener("click",function(e){
 var t=e.target;
 while(t && t!==navEl && t.tagName!=="A"){ t=t.parentNode; }
 if(t && t.tagName==="A"){ setMenu(false); }
});
window.addEventListener("hashchange",function(){ setMenu(false); });
window.addEventListener("hashchange",route);
route();
